import { test, expect } from '@playwright/test';

test.describe('Product List Functionality', () => {
  test('should display the product list with 6 items', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    await page.login('standard_user', 'secret_sauce');
    const productCards = await page.locators('.inventory_item');
    await expect(productCards).toBeVisible();
    await expect(productCards).toHaveLength(6);
  });

  test('should not display the product list when logged out', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    await expect(page.locator('.inventory_item')).toBeVisible();
    await expect(page.locator('.inventory_item')).toHaveLength(6);
  });
});
